// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Form } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Inputs/Form)

figma.connect(Form, FIGMA_NODE_URL, {
  props: {
    layout: figma.enum('layout', { 'dense': 'dense', 'sparse': 'sparse' }),
  },
  example: ({ layout }) => (
    <Form layout={layout}></Form>
  ),
});
